rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /a/{d} {
      allow read: if d == 'one';
      allow get: if d == 'two';
      allow read: if
        d == 'three';
    }
    match /{path=**} {
      allow get: if path == 'x';
    }
    match /b/{d} {
      allow get;
    }
    match /e/{d} {
      allow get: if d == 'zero' && request.auth.uid == 'u1';
      allow get: if debug(d) == 'q' || debug(request.auth.uid) == 'u1';
    }
    match /n/{d} {
      allow list: if false;
    }
  }
}

